<!--vbase-->
<template>
  <q-dialog
    :model-value="modelValue"
    persistent
    transition-show="scale"
    transition-hide="scale"
    @update:model-value="$emit('update:modelValue', $event)"
    @keydown.esc="close()"
  >
    <q-card style="width: 50%">
      <q-toolbar class="secondary-toolbar text-white">
        <q-toolbar-title>
          <span class="text-weight-bold">{{ $t('update_translation_key') }}</span>
        </q-toolbar-title>

        <q-btn flat round dense v-close-popup icon="close" @click="close()" />
      </q-toolbar>

      <q-card-section>
        <div class="flex flex-col gap-3">
          <q-input
            outlined
            dense
            hide-bottom-space
            readonly
            :model-value="name"
            data-cy="edit-translation-name"
            :label="$t(nameLabel)"
          />

          <q-input
            outlined
            dense
            hide-bottom-space
            v-model="editTitle"
            data-cy="edit-translation-title"
            :label="$t('title')"
          />

          <q-input
            outlined
            dense
            hide-bottom-space
            readonly
            v-model="editTranslationKey"
            data-cy="edit-translation-key"
            :label="$t('translation_key_label')"
          >
            <template #append>
              <q-btn
                flat
                dense
                round
                size="sm"
                color="primary"
                data-cy="generate-translation-key"
                @click="generateTranslationKey()"
              >
                <Icon icon="mdi:auto-fix" width="18" height="18" />
                <q-tooltip>{{ $t('generate_dynamic_translation') }}</q-tooltip>
              </q-btn>
            </template>
          </q-input>
        </div>

        <div class="mt-4 flex justify-center gap-2">
          <q-btn
            color="primary"
            :label="$t('back')"
            data-cy="edit-translation-back"
            @click="close()"
          />
          <q-btn
            color="primary"
            :label="$t('update')"
            data-cy="edit-translation-save"
            @click="submit()"
          />
        </div>
      </q-card-section>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, PropType } from 'vue';
import { notify } from 'src/components/notifications/notify';
import { useUserStore } from 'src/store/User/user_details.store';
import {
  getFieldTranslationKey,
  toTranslationKeySegment,
} from 'src/utils/fieldTranslationKey';

/**
 * The "Update Translation Key" dialog, shared by the field settings screen and
 * the doc-type custom columns screen.
 *
 * It owns the edit buffers, the org-prefixed key generation and the validation;
 * it does NOT persist. On Update it emits `save` with { title, translation_key }
 * and stays open, because the two callers write to different endpoints and only
 * they know whether the write succeeded.
 */
export default defineComponent({
  name: 'UpdateTranslationKeyDialog',
  props: {
    modelValue: {
      type: Boolean,
      default: false,
    },
    // The record being edited. Its title and translation key seed the form.
    row: {
      type: Object as PropType<Record<string, any> | null>,
      default: null,
    },
    // Which key on the row carries the immutable identifier.
    nameField: {
      type: String,
      default: 'field_name',
    },
    // Translation key for that identifier's input label.
    nameLabel: {
      type: String,
      default: 'field_name',
    },
  },
  emits: ['update:modelValue', 'save'],
  data() {
    return {
      editTitle: '',
      editTranslationKey: '',
    };
  },
  computed: {
    name(): string {
      return String(this.row?.[this.nameField] ?? '');
    },
  },
  watch: {
    modelValue: {
      immediate: true,
      handler(open: boolean) {
        if (open) {
          this.seedFromRow();
        }
      },
    },
  },
  methods: {
    seedFromRow() {
      this.editTitle = this.row?.title ?? '';
      this.editTranslationKey = getFieldTranslationKey(this.row);
    },

    close() {
      this.$emit('update:modelValue', false);
    },

    generateTranslationKey() {
      const org = toTranslationKeySegment(this.organizations?.[0]?.name);
      const base = toTranslationKeySegment(
        this.editTranslationKey || this.name,
      );

      // Re-generating an already-prefixed key must not stack the org name again.
      const alreadyPrefixed =
        org !== '' && (base === org || base.startsWith(org + '_'));

      this.editTranslationKey = alreadyPrefixed
        ? base
        : [org, base].filter((segment) => segment !== '').join('_');
    },

    validate(): boolean {
      const isBlank = (value: any) => String(value ?? '').trim() === '';

      if (isBlank(this.name)) {
        notify.error(this.$t('NAME_MANDATORY'));
        return false;
      }

      if (isBlank(this.editTitle)) {
        notify.error(this.$t('TITLE_MANDATORY'));
        return false;
      }

      if (isBlank(this.editTranslationKey)) {
        notify.error(this.$t('TRANSLATION_KEY_MANDATORY'));
        return false;
      }

      return true;
    },

    submit() {
      if (!this.validate()) {
        return;
      }

      this.$emit('save', {
        title: this.editTitle,
        translation_key: this.editTranslationKey,
      });
    },
  },
  setup() {
    const user_store = useUserStore();
    const { organizations } = storeToRefs(user_store);

    return { organizations };
  },
});
</script>
